#!/usr/bin/env bash
# Opt-in live OPcache probe test (CLI-21): serves the real health.php through
# a real FrankenPHP binary and asserts the web-process OPcache invariant —
# no negative/non-finite measurements leak, every nulled field carries a
# warning, INI settings stay listed separately. Passes on runtimes with and
# without the uninitialized-counters quirk. No system services, WordPress or
# MariaDB involved; everything runs in a temp HOME with loopback only.
# shellcheck disable=SC1091 # Compiled CLI is generated by compile.sh.
set -euo pipefail
[ -n "${PLAK_TEST_FRANKENPHP:-}" ] || { echo 'OPcache probe live test skipped: set PLAK_TEST_FRANKENPHP'; exit 0; }
[ -x "$PLAK_TEST_FRANKENPHP" ] || { echo 'PLAK_TEST_FRANKENPHP must point to an executable binary.' >&2; exit 1; }
ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$ROOT_DIR"
./compile.sh >/dev/null
tmpdir=$(mktemp -d /tmp/opencode/plak-opcache-test.XXXXXX)
pid=""
cleanup() { [ -z "$pid" ] || { kill "$pid" 2>/dev/null || true; wait "$pid" 2>/dev/null || true; }; rm -rf "$tmpdir"; }
trap cleanup EXIT
export HOME="$tmpdir/home" PLAK_NO_PATH_PRELUDE=1 XDG_DATA_HOME="$tmpdir/data" XDG_CONFIG_HOME="$tmpdir/config"
mkdir -p "$HOME"
source ./plak.sh >/dev/null
create_gui_file >/dev/null
printf 'memory_limit=256M\nopcache.enable=1\nopcache.memory_consumption=128\n' > "$PHP_INI_FILE"
read -r http_port https_port < <(python3 - <<'PY'
import socket
sockets=[socket.socket() for _ in range(2)]
for s in sockets: s.bind(('127.0.0.1',0))
print(*(s.getsockname()[1] for s in sockets))
PY
)
cat > "$tmpdir/Caddyfile" <<CADDY
{
    admin off
    skip_install_trust
    default_bind 127.0.0.1
    http_port $http_port
    https_port $https_port
}
https://127.0.0.1:$https_port {
    root * "$GUI_DIR"
    php_server
    tls internal
}
CADDY
PHPRC="$PHP_INI_FILE" "$PLAK_TEST_FRANKENPHP" run --config "$tmpdir/Caddyfile" > "$tmpdir/server.log" 2>&1 &
pid=$!
for _ in {1..100}; do
    if curl --noproxy '*' -ksf --max-time 1 "https://127.0.0.1:$https_port/health.php" > "$tmpdir/probe.json" 2>/dev/null; then break; fi
    sleep 0.1
done
curl --noproxy '*' -ksf --max-time 5 "https://127.0.0.1:$https_port/health.php?format=text" > "$tmpdir/probe.txt"
python3 - "$tmpdir/probe.json" "$tmpdir/probe.txt" <<'PY'
import json,math,sys
report=json.load(open(sys.argv[1])); text=open(sys.argv[2]).read()
assert report['source']=='web', report
status=report['opcache_status']; assert status is not None, report
mu=status['memory_usage']
for key in ('used_memory','free_memory','wasted_memory'):
    value=mu.get(key)
    if value is not None: assert isinstance(value,(int,float)) and value>=0, (key,value)
wasted=mu.get('current_wasted_percentage')
if wasted is not None: assert math.isfinite(float(wasted)), wasted
limits=report['opcache_configuration'] or {}
for key in ('opcache.memory_consumption','opcache.interned_strings_buffer','opcache.max_accelerated_files'):
    if limits.get(key) is not None: assert limits[key]>0, (key,limits[key])
nulled=[k for k,v in list(mu.items())+[('current_wasted_percentage',wasted)]+[(k,limits.get(k)) for k in ('opcache.memory_consumption',)] if v is None]
if nulled: assert report['opcache_warnings'], report
assert 'cache_full' in status and 'hits' in status.get('opcache_statistics',{})
assert 'Web OPcache cache_full:' in text and 'Web INI settings' in text
PY
echo 'Live web OPcache probe invariant passed (real FrankenPHP, not CLI cache)'
